43	export class BestiaryApi {
44	    private static throttle = ApiThrottle.getInstance();
45	    private static weaknessMap: Record<string, number> | null = null;
46	
47	    /**
48	     * Fetches the canonical mapping of weakness names to IDs.
49	     * Cached for the duration of the session.
50	     */
51	    public static async fetchWeaknessNames(): Promise<Record<string, number>> {
52	        if (this.weaknessMap) return this.weaknessMap;
53	
54	        await this.throttle.acquire('bestiary');
55	        try {
56	            const res = await fetch(`${BESTIARY_BASE}/weaknessNames.json`, {
57	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
58	                signal: AbortSignal.timeout(10000)
59	            });
60	            if (!res.ok) throw new Error(`Weakness fetch failed: ${res.status}`);
61	            this.weaknessMap = await res.json() as Record<string, number>;
62	            return this.weaknessMap;
63	        } catch (err) {
64	            logger.error({ err }, 'Failed to fetch weakness names.');
65	            return {};
66	        }
