69	    /**
70	     * Search for beasts by name/term.
71	     * @param term Search term (e.g., "Cow"). Supports multiple terms separated by '+'.
72	     */
73	    public static async searchBeasts(term: string): Promise<BestiarySearchEntry[]> {
74	        await this.throttle.acquire('bestiary');
75	        try {
76	            const url = `${BESTIARY_BASE}/beastSearch.json?term=${encodeURIComponent(term)}`;
