83	        } catch (err) {
84	            logger.error({ term, err }, 'Beast search failed.');
85	            return [];
86	        }
87	    }
88	
89	    /**
90	     * Fetch authoritative beast data by official ID.
91	     * @param beastId The canonical RS3 Beast ID.
92	     */
93	    public static async getBeastData(beastId: number): Promise<BestiaryBeastData | null> {
94	        await this.throttle.acquire('bestiary');
95	
96	        const url = `${BESTIARY_BASE}/beastData.json?beastid=${beastId}`;
97	        try {
98	            const res = await fetch(url, {
99	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
100	                signal: AbortSignal.timeout(10000)
101	            });
102	
103	            if (!res.ok) {
104	                logger.warn({ beastId, status: res.status }, 'Bestiary API non-OK response.');
105	                return null;
106	            }
107	
108	            const data = await res.json() as any;
109	            if (!data) return null;
110	
111	            return {
112	                id: data.id,
113	                name: data.name,
114	                examine: data.description,
115	                combatLevel: data.level,
116	                lifepoints: data.lifepoints,
117	                attack: data.attack,
118	                defence: data.defence,
119	                magic: data.magic,
120	                ranged: data.ranged,
121	                weakness: data.weakness,
122	                slayerLevel: data.slayerlevel,
123	                slayerCategory: data.slayercat,
124	                size: data.size,
125	                aggressive: data.aggressive,
126	                poisonous: data.poisonous,
127	                areas: Array.isArray(data.areas) ? data.areas : [],
128	                animations: data.animations || {},
129	                members: data.members === 'true' || data.members === true,
130	                xp: parseFloat(data.xp || '0'),
131	            };
132	        } catch (err) {
133	            logger.error({ beastId, err }, 'Failed to fetch beast data.');
134	            return null;
135	        }
136	    }
137	
138	    /**
139	     * Returns a list of all area names present in the Bestiary.
140	     */
141	    public static async getAreaNames(): Promise<string[]> {
142	        await this.throttle.acquire('bestiary');
143	        try {
144	            const res = await fetch(`${BESTIARY_BASE}/areaNames.json`, {
145	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
