174	
175	    /**
176	     * Returns a mapping of Slayer category names to their IDs.
177	     */
178	    public static async getSlayerCategories(): Promise<Record<string, number>> {
179	        await this.throttle.acquire('bestiary');
180	        try {
181	            const res = await fetch(`${BESTIARY_BASE}/slayerCatNames.json`, {
182	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
183	                signal: AbortSignal.timeout(10000)
184	            });
185	            if (!res.ok) return {};
186	            return await res.json() as Record<string, number>;
187	        } catch (err) {
188	            logger.error({ err }, 'Failed to fetch slayer categories.');
189	            return {};
190	        }
191	    }
192	
193	    /**
194	     * Returns monsters within a specific slayer category.
195	     */
196	    public static async getBeastsInSlayerCategory(catId: number): Promise<BestiarySearchEntry[]> {
197	        await this.throttle.acquire('bestiary');
198	        try {
199	            const url = `${BESTIARY_BASE}/slayerBeasts.json?identifier=${catId}`;
200	            const res = await fetch(url, {
201	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
202	                signal: AbortSignal.timeout(10000)
203	            });
204	            if (!res.ok) return [];
205	            return await res.json() as BestiarySearchEntry[];
206	        } catch (err) {
207	            logger.error({ catId, err }, 'Failed to fetch beasts in slayer category.');
208	            return [];
209	        }
210	    }
211	
212	    /**
213	     * Returns monsters with a specific weakness.
214	     */
215	    public static async getBeastsWithWeakness(weaknessId: number): Promise<BestiarySearchEntry[]> {
216	        await this.throttle.acquire('bestiary');
217	        try {
218	            const url = `${BESTIARY_BASE}/weaknessBeasts.json?identifier=${weaknessId}`;
219	            const res = await fetch(url, {
220	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
221	                signal: AbortSignal.timeout(10000)
