223	            if (!res.ok) return [];
224	            return await res.json() as BestiarySearchEntry[];
225	        } catch (err) {
226	            logger.error({ weaknessId, err }, 'Failed to fetch beasts with weakness.');
227	            return [];
228	        }
229	    }
230	
231	    /**
232	     * Returns monsters within a combat level range.
233	     */
234	    public static async getBeastsInLevelRange(min: number, max: number): Promise<BestiarySearchEntry[]> {
235	        await this.throttle.acquire('bestiary');
236	        try {
237	            const url = `${BESTIARY_BASE}/levelGroup.json?identifier=${min}-${max}`;
238	            const res = await fetch(url, {
239	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
240	                signal: AbortSignal.timeout(10000)
241	            });
242	            if (!res.ok) return [];
243	            return await res.json() as BestiarySearchEntry[];
244	        } catch (err) {
245	            logger.error({ min, max, err }, 'Failed to fetch beasts in level range.');
246	            return [];
247	        }
