249	
250	    /**
251	     * Returns all monsters whose names start with a specific letter.
252	     */
253	    public static async getBeastsByLetter(letter: string): Promise<any[]> {
254	        await this.throttle.acquire('bestiary');
255	        try {
256	            const url = `${BESTIARY_BASE}/bestiaryNames.json?letter=${encodeURIComponent(letter)}`;
257	            const res = await fetch(url, {
258	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
