1	/**
2	 * GeApi.ts
3	 *
4	 * High-fidelity interface for the Official RuneScape Grand Exchange Database.
5	 * Provides real-time prices, market trends, and historical price graphs.
6	 *
7	 * Endpoint: https://secure.runescape.com/m=itemdb_rs/api/catalogue
8	 */
9	
10	import { ApiThrottle } from './ApiThrottle.js';
11	import { createLogger } from './logger.js';
12	
13	const logger = createLogger('GeApi');
14	const GE_BASE = 'https://secure.runescape.com/m=itemdb_rs/api/catalogue';
15	
16	export interface GeItemDetails {
17	    id: number;
18	    name: string;
19	    description: string;
20	    current: {
21	        trend: string;
22	        price: string; // API returns strings like "5.2m" or "1200"
23	    };
24	    today: {
25	        trend: string;
26	        price: string;
27	    };
28	    day30: {
29	        trend: string;
30	        change: string;
31	    };
32	    day90: {
33	        trend: string;
34	        change: string;
35	    };
36	    day180: {
37	        trend: string;
38	        change: string;
39	    };
40	    members: string; // "true" or "false"
41	}
42	
43	export class GeApi {
44	    private static throttle = ApiThrottle.getInstance();
45	
46	    /**
47	     * Fetch real-time item details by official game ID.
48	     * @param itemId The canonical RS3 Item ID.
49	     */
50	    public static async getItemDetails(itemId: number): Promise<GeItemDetails | null> {
51	        await this.throttle.acquire('ge');
52	
53	        const url = `${GE_BASE}/detail.json?item=${itemId}`;
54	        try {
55	            const res = await fetch(url, {
56	                headers: { 'User-Agent': 'POG2-Sovereign/1.0 (Ground Truth Engine)' },
57	                signal: AbortSignal.timeout(10000)
58	            });
59	
60	            if (!res.ok) {
61	                logger.warn({ itemId, status: res.status }, 'GE API non-OK response.');
62	                return null;
63	            }
64	
65	            const data = await res.json() as any;
66	            if (!data || !data.item) return null;
67	
68	            return data.item as GeItemDetails;
69	        } catch (err) {
70	            logger.error({ itemId, err }, 'Failed to fetch GE item details.');
71	            return null;
72	        }
73	    }
74	
75	    /**
76	     * Fetch 180-day price graph for specific item.
77	     * Returns a sorted array of price values.
78	     */
79	    public static async getPriceGraph(itemId: number): Promise<number[]> {
80	        await this.throttle.acquire('ge');
81	
82	        const url = `${GE_BASE}/graph.json?item=${itemId}`;
83	        try {
84	            const res = await fetch(url, {
85	                headers: { 'User-Agent': 'POG2-Sovereign/1.0' },
86	                signal: AbortSignal.timeout(10000)
87	            });
88	
89	            if (!res.ok) return [];
90	
91	            const data = await res.json() as { daily: Record<string, number> };
92	            if (!data || !data.daily) return [];
93	
94	            // Convert { "1720000000000": 1234, ... } to sorted numeric array
95	            return Object.entries(data.daily)
96	                .sort((a, b) => parseInt(a[0]) - parseInt(b[0]))
97	                .map(([, price]) => price);
98	        } catch (err) {
99	            logger.error({ itemId, err }, 'Failed to fetch GE price graph.');
100	            return [];
101	        }
102	    }
103	
104	    /**
105	     * Parses GE price strings (e.g., "5.2m", "1.1k") into raw integers.
106	     */
107	    public static parseGePrice(priceStr: string): number {
108	        if (!priceStr) return 0;
109	        const clean = priceStr.toLowerCase().trim();
110	        if (clean.endsWith('m')) {
111	            return Math.floor(parseFloat(clean.replace('m', '')) * 1000000);
112	        }
113	        if (clean.endsWith('k')) {
114	            return Math.floor(parseFloat(clean.replace('k', '')) * 1000);
115	        }
116	        const val = parseInt(clean.replace(/,/g, ''), 10);
117	        return isNaN(val) ? 0 : val;
118	    }
119	}
