1	/**
2	 * WikiEquipmentEnricher.ts
3	 *
4	 * Structured parser for RS Wiki Infobox templates and drop tables.
5	 * Extracts equipment bonuses, item metadata, monster stats, and complete
6	 * drop tables (including sub-table resolution) with respectful rate limiting.
7	 *
8	 * Sovereign Substrate: Semantic Enrichment Layer
9	 * Cache Authority: D:\sovereign\atlas\wiki\cache\
10	 *
11	 * Template Coverage:
12	 *   - {{Infobox Bonuses}}  → Equipment combat stats
13	 *   - {{Infobox Item}}     → Item metadata
14	 *   - {{Infobox Monster}}  → Monster/NPC stats
15	 *   - {{DropsLine}}        → Individual drop entries
16	 *   - {{Rare drop table}}, {{Gem drop table}}, etc. → Sub-table resolution
17	 */
18	
19	import { createLogger } from './logger.js';
20	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
21	import { join } from 'path';
22	import { QueryClassifier, QueryType } from './QueryClassifier.js';
23	import { CacheForensicsLimb } from '../limbs/spatial/CacheForensicsLimb.js';
24	
25	const logger = createLogger('WikiEquipmentEnricher');
26	
27	// ═══════════════════════════════════════════════════════
28	// Interfaces
29	// ═══════════════════════════════════════════════════════
30	
31	export interface WikiEquipmentBonuses {
32	    tier: number;
33	    slot: string;          // mainhand, off-hand, 2h, head, body, legs, feet, hands, back, neck, ring, ammo, pocket, shield
