96	
97	export interface WikiPageData {
98	    title: string;
99	    fetchedAt: number;
100	    bonuses: WikiEquipmentBonuses | null;
101	    itemMeta: WikiItemMeta | null;
102	    monsterMeta: WikiMonsterMeta | null;
103	    dropTables: WikiDropTable[];
104	    rawVariables: Record<string, string>;
105	    pageType?: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
106	    extract?: string;
107	    categoryMembers?: string[];
