119	
120	// ═══════════════════════════════════════════════════════
121	// Generic Enrichment Types
122	// ═══════════════════════════════════════════════════════
123	
124	export interface WikiGenericMeta {
125	    title: string;
126	    pageType: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
127	    extract: string;
128	    infoboxVars: Record<string, string>;
129	    categoryMembers?: string[];
130	    fetchedAt: number;
131	}
132	
133	export class WikiEquipmentEnricher {
134	    private static instance: WikiEquipmentEnricher;
135	
136	    private readonly API_BASE = 'https://runescape.wiki/api.php';
137	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; admin@pog2.internal; respectful-soft-parse; +https://github.com/Kbro1989/POG2)';
138	    private readonly RATE_LIMIT_MS = 1500;
139	    private readonly CACHE_DIR: string;
140	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
141	
142	    private lastRequestTime = 0;
143	    private requestCount = 0;
144	
145	    private constructor() {
146	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
147	        this.ensureCacheDir();
148	    }
149	
150	    public static getInstance(): WikiEquipmentEnricher {
151	        if (!this.instance) {
152	            this.instance = new WikiEquipmentEnricher();
153	        }
154	        return this.instance;
155	    }
156	
157	    // ── Cache Layer ────────────────────────────────────────
158	
159	    private ensureCacheDir(): void {
160	        const dirs = [
161	            this.CACHE_DIR,
162	            join(this.CACHE_DIR, 'items'),
163	            join(this.CACHE_DIR, 'monsters'),
164	            join(this.CACHE_DIR, 'templates'),
165	            join(this.CACHE_DIR, 'wikitext'),
166	            join(this.CACHE_DIR, 'generic')
167	        ];
168	        for (const dir of dirs) {
169	            if (!existsSync(dir)) {
170	                mkdirSync(dir, { recursive: true });
171	            }
172	        }
173	    }
174	
175	    private sanitizeFilename(name: string): string {
176	        return name.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').toLowerCase();
177	    }
178	
179	    private readCache(subdir: string, key: string): any | null {
180	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
181	        if (!existsSync(filePath)) return null;
182	
183	        try {
184	            const raw = readFileSync(filePath, 'utf8');
185	            const cached = JSON.parse(raw);
186	
187	            // TTL check
188	            if (cached._cachedAt && (Date.now() - cached._cachedAt) > this.CACHE_TTL_MS) {
189	                logger.debug({ key }, 'Cache expired, will re-fetch.');
190	                return null;
191	            }
192	
193	            return cached;
194	        } catch {
195	            return null;
196	        }
197	    }
198	
199	    private writeCache(subdir: string, key: string, data: any): void {
200	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
201	        try {
202	            writeFileSync(filePath, JSON.stringify({ ...data, _cachedAt: Date.now() }, null, 2), 'utf8');
203	        } catch (err) {
204	            logger.warn({ key, err }, 'Failed to write cache.');
205	        }
206	    }
207	
208	    // ── Rate Limiter ───────────────────────────────────────
209	
210	    private async throttle(): Promise<void> {
211	        const now = Date.now();
212	        const elapsed = now - this.lastRequestTime;
213	        if (elapsed < this.RATE_LIMIT_MS) {
214	            const delay = this.RATE_LIMIT_MS - elapsed;
215	            await new Promise(resolve => setTimeout(resolve, delay));
216	        }
217	        this.lastRequestTime = Date.now();
218	        this.requestCount++;
219	    }
220	
221	    // ── API Layer ──────────────────────────────────────────
222	
223	    /**
224	     * Fetch raw wikitext for a page. Checks disk cache first.
225	     */
226	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
227	        const cached = this.readCache('wikitext', pageTitle);
228	        if (cached?.wikitext) {
229	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
230	            return cached.wikitext;
231	        }
232	
233	        await this.throttle();
234	
235	        const params = new URLSearchParams({
236	            action: 'parse',
237	            format: 'json',
238	            page: pageTitle,
239	            prop: 'wikitext',
240	            origin: '*'
241	        });
242	
243	        try {
244	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
245	                headers: {
246	                    'User-Agent': this.USER_AGENT,
247	                    'Accept': 'application/json'
248	                },
249	                signal: AbortSignal.timeout(10000)
250	            });
251	
252	            if (!response.ok) {
253	                if (response.status === 429) {
254	                    const retryAfter = response.headers.get('Retry-After');
255	                    if (retryAfter) {
