357	    /**
358	     * Extract a single template's parameters from wikitext.
359	     * Handles nested templates via bracket-depth tracking.
360	     */
361	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
362	        const lowerText = wikitext.toLowerCase();
363	        const lowerName = templateName.toLowerCase();
364	
365	        let searchIdx = 0;
366	        let startIdx = -1;
367	
368	        while (searchIdx < lowerText.length) {
369	            const bracePos = lowerText.indexOf('{{', searchIdx);
370	            if (bracePos === -1) break;
371	
372	            let nameStart = bracePos + 2;
373	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
374	
375	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
376	                const afterName = lowerText[nameStart + lowerName.length];
377	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
378	                    startIdx = bracePos;
379	                    break;
380	                }
381	            }
382	            searchIdx = bracePos + 2;
383	        }
384	
385	        if (startIdx === -1) return null;
386	
387	        // Find matching closing }} using bracket depth
388	        let depth = 0;
389	        let endIdx = startIdx;
390	        for (let i = startIdx; i < wikitext.length - 1; i++) {
391	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
392	                depth++;
393	                i++;
394	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
395	                depth--;
396	                i++;
397	                if (depth === 0) {
398	                    endIdx = i + 1;
399	                    break;
400	                }
401	            }
402	        }
403	
404	        if (depth !== 0) return null;
405	
406	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
407	        const pipeIdx = fullContent.indexOf('|');
408	        if (pipeIdx === -1) return {};
409	
410	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
411	    }
