413	    /**
414	     * Extract ALL instances of a template from wikitext.
415	     * Critical for DropsLine parsing where each drop is a separate template call.
416	     */
417	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
418	        const results: Record<string, string>[] = [];
419	        const lowerText = wikitext.toLowerCase();
420	        const lowerName = templateName.toLowerCase();
421	        let searchIdx = 0;
422	
423	        while (searchIdx < lowerText.length) {
424	            const bracePos = lowerText.indexOf('{{', searchIdx);
425	            if (bracePos === -1) break;
426	
427	            let nameStart = bracePos + 2;
428	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
429	
430	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
431	                const afterName = lowerText[nameStart + lowerName.length];
432	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
433	                    // Find closing braces
434	                    let depth = 0;
435	                    let endIdx = bracePos;
436	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
437	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
438	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
439	                            depth--; i++;
440	                            if (depth === 0) { endIdx = i + 1; break; }
441	                        }
442	                    }
443	
444	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
445	                    const pipeIdx = fullContent.indexOf('|');
446	                    if (pipeIdx !== -1) {
447	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
448	                    }
449	
450	                    searchIdx = endIdx;
451	                    continue;
452	                }
453	            }
454	            searchIdx = bracePos + 2;
455	        }
456	
457	        return results;
458	    }
