460	    /**
461	     * Parse pipe-separated template parameters, respecting nested template depth.
462	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
463	     */
464	    private parseTemplateParams(text: string): Record<string, string> {
465	        const params: Record<string, string> = {};
466	        let depth = 0;
467	        let currentParam = '';
468	        let positionalIdx = 1;
469	
470	        for (let i = 0; i < text.length; i++) {
471	            const ch = text[i];
472	            const next = text[i + 1];
473	
474	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
475	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
476	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
477	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
478	            else if (ch === '|' && depth === 0) {
479	                this.assignParam(params, currentParam, positionalIdx);
480	                positionalIdx++;
481	                currentParam = '';
482	            } else {
483	                currentParam += ch;
484	            }
485	        }
486	
487	        // Last parameter
488	        if (currentParam.trim()) {
489	            this.assignParam(params, currentParam, positionalIdx);
490	        }
491	
492	        return params;
493	    }
494	
495	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
496	        const eqIdx = raw.indexOf('=');
497	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
498	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
499	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
500	            if (key) params[key] = value;
501	        } else {
502	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
503	        }
504	    }
