506	    /**
507	     * Strip wiki markup from a value (links, formatting, refs).
508	     */
509	    private cleanWikiMarkup(text: string): string {
510	        return text
511	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
512	            .replace(/'''?/g, '')                                // Bold/italic
513	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
514	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
515	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
516	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
517	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
518	            .trim();
519	    }
