698	     * Fetch and parse a sub-drop-table template page.
699	     * These live at Template:{name} on the wiki.
700	     */
701	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
702	        // Check cache
703	        const cached = this.readCache('templates', templateName);
704	        if (cached?.entries) {
705	            logger.debug({ templateName }, 'Sub-table served from cache.');
706	            return cached.entries;
707	        }
708	
709	        // Fetch the template page
710	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
711	        if (!wikitext) return [];
712	
713	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
714	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
715	            itemName: dl['name'] || dl['_1'] || 'Unknown',
716	            quantity: dl['quantity'] || dl['_2'] || '1',
717	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
718	            isMembers: this.safeBool(dl['members']),
719	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
720	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
721	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
722	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
723	        }));
724	
725	        // Cache the resolved sub-table
726	        this.writeCache('templates', templateName, { entries });
727	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
728	
729	        return entries;
730	    }
