934	    /**
935	     * Unified entry point for entity resolution.
936	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
937	     */
938	    public async enrichEntity(query: string): Promise<any> {
939	        const classified = QueryClassifier.classify(query);
940	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
941	
942	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
943	        if (classified.type.startsWith('structural_')) {
944	            const forensics = CacheForensicsLimb.getInstance();
945	            const id = classified.extractedIds[0];
946	
947	            if (classified.type === 'structural_enum') {
948	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
949	            }
950	            if (classified.type === 'structural_id') {
951	                const item = await forensics.getItemDetails(id);
952	                const npc = await forensics.getNpcDetails(id);
953	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
954	            }
955	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
956	        }
957	
958	        // 2. Route Spatial Queries
959	        if (classified.type.startsWith('spatial_')) {
960	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
961	        }
962	
963	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
964	        const name = classified.extractedNames[0] || query;
965	
966	        // Try monster first, then item, then generic
967	        const monster = await this.enrichMonster(name);
968	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
969	
970	        const item = await this.enrichItem(name);
971	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
972	
973	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
974	    }
