990	            const dateMatch = block.match(/(\d{1,2}\s\w+ \d{4})/);
991	            if (!dateMatch) continue;
992	
993	            const date = dateMatch[1];
994	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
