1000	                category: 'General',
1001	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1002	                isHotfix: block.toLowerCase().includes('hotfix'),
1003	                isColdfix: false,
1004	                affectedEntities: [] // Would require further parsing of the block text for IDs
1005	            });
1006	        }
