1	/**
2	 * ApiThrottle.ts
3	 *
4	 * Shared rate-limiting utility for RS3 official APIs.
5	 * Prevents 429 (Too Many Requests) errors by implementing a Token Bucket algorithm
6	 * per API domain.
7	 */
8	
9	import { createLogger } from './logger.js';
10	
11	const logger = createLogger('ApiThrottle');
12	
13	/**
14	 * TokenBucket implementation for precision rate limiting.
15	 */
16	class TokenBucket {
17	    private tokens: number;
18	    private lastRefill: number;
19	    private readonly capacity: number;
20	    private readonly refillRate: number; // tokens per millisecond
21	    private retryAfterUntil: number = 0;
22	
23	    constructor(capacity: number, refillPeriodMs: number) {
24	        this.capacity = capacity;
25	        this.refillRate = capacity / refillPeriodMs;
26	        this.tokens = capacity;
27	        this.lastRefill = Date.now();
28	    }
29	
30	    async consume(amount: number = 1): Promise<void> {
31	        while (true) {
32	            const now = Date.now();
33	
34	            // Check for active Retry-After block
35	            if (now < this.retryAfterUntil) {
36	                const waitTime = this.retryAfterUntil - now;
37	                await new Promise(resolve => setTimeout(resolve, waitTime));
38	                continue;
39	            }
40	
41	            const delta = now - this.lastRefill;
42	
43	            // Refill tokens based on elapsed time
44	            this.tokens = Math.min(this.capacity, this.tokens + delta * this.refillRate);
45	            this.lastRefill = now;
46	
47	            if (this.tokens >= amount) {
48	                this.tokens -= amount;
49	                return;
50	            }
51	
52	            // Wait until enough tokens are available
53	            const waitTime = (amount - this.tokens) / this.refillRate;
54	            await new Promise(resolve => setTimeout(resolve, waitTime));
55	        }
56	    }
57	
58	    public setRetryAfter(seconds: number): void {
59	        this.retryAfterUntil = Date.now() + (seconds * 1000);
60	    }
61	}
62	
63	export class ApiThrottle {
64	    private static instance: ApiThrottle;
65	    private readonly buckets: Map<string, TokenBucket> = new Map();
66	
67	    private constructor() {
68	        // Jagex Observed Rate Limits
69	        this.buckets.set('ge', new TokenBucket(100, 60 * 1000));        // 100 req/min
70	        this.buckets.set('bestiary', new TokenBucket(50, 60 * 1000));    // 50 req/min
71	        this.buckets.set('hiscores', new TokenBucket(300, 60 * 1000)); // 300 req/min
72	        this.buckets.set('runemetrics', new TokenBucket(100, 60 * 1000)); // 100 req/min
73	        this.buckets.set('wiki', new TokenBucket(40, 60 * 1000));       // 40 req/min (~1.5s interval)
74	    }
75	
76	    public static getInstance(): ApiThrottle {
77	        if (!this.instance) {
78	            this.instance = new ApiThrottle();
79	        }
80	        return this.instance;
81	    }
82	
83	    /**
84	     * Requests permission to call a specific API domain.
85	     * @param domain The API bucket to use ('ge', 'bestiary', 'hiscores', 'runemetrics', 'wiki').
86	     */
87	    public async acquire(domain: string): Promise<void> {
88	        const bucket = this.buckets.get(domain);
89	        if (!bucket) {
90	            logger.warn({ domain }, 'Unknown API domain requested. Using default wiki bucket.');
91	            return this.acquire('wiki');
92	        }
93	        await bucket.consume();
94	    }
95	
96	    /**
97	     * Reports a 429 Retry-After signal from a remote server.
98	     * @param domain The API bucket to throttle.
99	     * @param seconds The number of seconds to wait before resuming.
100	     */
101	    public reportRetryAfter(domain: string, seconds: number): void {
102	        const bucket = this.buckets.get(domain);
103	        if (bucket) {
104	            logger.warn({ domain, seconds }, 'Applying Retry-After throttle from server.');
105	            bucket.setRetryAfter(seconds);
106	        }
107	    }
